select 'Weekly Arena 2026-W46', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-11-10T00:00:00.000Z', '2026-11-17T00:00:00.000Z', 60, 'published', $WK6ee570387252$[{"id":"wk-2026-w46-01-b1b5","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $21$ and $7$ and each non-parallel side has length $25$. Find its area.","type":"text","correctAnswer":"336","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $7$ and hypotenuse $25$.","solution":"The height is $\\sqrt{25^2-7^2}=24$, so the area is $\\tfrac12(21+7)(24)=336$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w46-02-d6d0","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $498$ that are divisible by $10$ or by $3$ (or both).","type":"text","correctAnswer":"49753","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $10$, $3$ and $30$ gives $49753$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2026-w46-03-940b","title":"Coprime Count","topic":"Number Theory","level":"Intermediate","question":"How many integers $n$ with $1\\le n\\le 458$ are relatively prime to $39$?","type":"text","correctAnswer":"282","hint":"Remove multiples of 3, 13 using inclusion-exclusion.","solution":"Inclusion-exclusion over the primes 3, 13 leaves $282$ integers.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w46-04-0c32","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 3$. Find $x^{5} + \\dfrac{1}{x^{5}}$.","type":"text","correctAnswer":"123","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=3T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=3$ the recurrence gives $T_{5}=123$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w46-05-04f5","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $14$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=7$. Find $PA + PB + PT$.","type":"text","correctAnswer":"49","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=14^2/7=28$, so the sum is $7+28+14=49$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w46-06-baea","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(13,11)$ and $(6,6)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"3","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $12$ and the boundary has $B=8$ lattice points, so $I=(12-8+2)/2=3$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w46-07-987f","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 4-tuples $(x_1,\\dots,x_4)$ of non-negative integers satisfy $x_1+\\cdots+x_4=10$ with every $x_i\\le 7$?","type":"text","correctAnswer":"246","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $246$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2026-w46-08-b627","title":"Rearranging a Word","topic":"Combinatorics","level":"Advanced","question":"In how many distinct ways can the letters of $\\text{CLLJJFFF}$ be rearranged so that no two identical letters are adjacent?","type":"text","correctAnswer":"384","hint":"Count all arrangements, then use inclusion-exclusion by gluing identical letters together.","solution":"Inclusion-exclusion (confirmed by exhaustive enumeration) gives $384$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":4,"points":73,"difficulty":0.52},{"id":"wk-2026-w46-09-03a7","title":"The Last Three Digits","topic":"Number Theory","level":"Advanced","question":"Find the remainder when $47^{229}$ is divided by $1000$.","type":"text","correctAnswer":"567","hint":"Work modulo $8$ and modulo $125$ separately and combine, or use the order of the unit in $(\\mathbb Z/1000)^\\times$.","solution":"Modular exponentiation gives $47^{229}\\equiv 567 \\pmod{1000}$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w46-10-0f38","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{69} \\left\\lfloor \\frac{7k}{8} \\right\\rfloor$.","type":"text","correctAnswer":"2082","hint":"Write $7k=8q+r$ and track how the remainder cycles with period $8$.","solution":"Evaluating each floor term and adding gives $2082$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK6ee570387252$::jsonb
